private async fetchBug(bugId: number): Promise<RawBug> {
  const pat = ADO_PAT;
  const org = process.env.ADO_ORGANIZATION || 'my-org';
  const proj = process.env.ADO_PROJECT || 'MyProject';
  // $expand=all forces the HTML description + repro fields the draft needs (a plain GET omits them)
  const url = `https://dev.azure.com/${org}/${proj}/_apis/wit/workitems/${bugId}?$expand=all&api-version=7.1`;
  // ADO PAT auth: Basic with EMPTY username + PAT as password -> the leading colon is intentional
  const auth = `Basic ${Buffer.from(`:${pat}`).toString('base64')}`;

  const resp = await fetch(url, { headers: { Authorization: auth } });
  const data = await resp.json();
  const f = data.fields || {};

  const title = f['System.Title'] || '';
  // Tolerates US1234 / US_1234 / US 1234, case-insensitive; captures digits only
  const storyMatch = title.match(/US[_\s]?(\d{4,6})/i);
  const storyRef = storyMatch ? `US${storyMatch[1]}` : '';

  return {
    id: bugId, title,
    priority: f['Microsoft.VSTS.Common.Priority'] || 3, // default to P3 when unset
    severity: f['Microsoft.VSTS.Common.Severity'] || '',
    descriptionHtml: f['System.Description'] || '',
    reproStepsHtml: f['Microsoft.VSTS.TCM.ReproSteps'] || '',
    storyRef,
    reportedBy: extractName(f['System.CreatedBy']), // identity object -> plain name
    // ... plus assignee, tags, and plain-text versions of each field
  };
}

function loadStoryIntelligence(bug: RawBug): StoryIntelligence {
  const empty: StoryIntelligence = { storyId: '', storyTitle: '', summary: '', found: false /* ... */ };

  // Try the title's captured group first, then fall back to storyRef (bare \d has no group -> [0])
  const storyNumMatch = bug.title.match(/US[_\s]?(\d{4,6})/i) || bug.storyRef.match(/\d{4,6}/);
  if (!storyNumMatch) return empty;
  const storyNum = storyNumMatch[1] || storyNumMatch[0];

  for (const [, storyDir] of Object.entries(INTELLIGENCE_DIRS)) {
    const candidate = path.join(storyDir, `US-${storyNum}.json`);
    if (!fs.existsSync(candidate)) continue; // missing briefing is normal — try the next dir

    const raw = JSON.parse(fs.readFileSync(candidate, 'utf-8'));
    return {
      storyId: String(raw.storyId || storyNum),
      storyTitle: raw.storyTitle || raw.title || '',
      summary: (raw.summary || '').slice(0, 600), // bound tokens + exposure — never the whole file
      // Flatten each element (object OR plain string) then cap the list length
      acceptanceCriteria: (raw.acceptanceCriteria || []).map((a: any) => a.description || String(a)).slice(0, 10),
      businessRules: (raw.businessRules || []).map((r: any) => r.description || String(r)).slice(0, 8),
      found: true,
    };
  }
  return empty; // no briefing found -> found:false, agent proceeds without grounding
}

async function extractScreenshots(bug: RawBug): Promise<BugScreenshot[]> {
  const screenshots: BugScreenshot[] = [];
  const combinedHtml = (bug.descriptionHtml || '') + (bug.reproStepsHtml || ''); // catch imgs in EITHER field
  const imgRegex = /<img[^>]+src=["']([^"']+)["'][^>]*>/gi;
  const MAX_IMAGES = 4;
  let match: RegExpExecArray | null;

  // Loop stops as soon as 4 are collected — bounds request size, doesn't parse the whole doc
  while ((match = imgRegex.exec(combinedHtml)) !== null && screenshots.length < MAX_IMAGES) {
    const src = match[1];
    if (src.startsWith('data:image')) {
      const mimeType = src.match(/data:(image\/\w+);base64,/)?.[1] || 'image/png'; // real mime from the URI
      const base64 = src.split(',')[1]; // everything after the comma is the payload
      // >100 guard drops tracking pixels / truncated or garbage srcs
      if (base64 && base64.length > 100) screenshots.push({ mimeType, base64, source: 'inline' });
    } else if (src.includes('dev.azure.com')) {
      // Attachment URLs are access-controlled — must fetch WITH auth, then re-encode
      const resp = await fetch(src, { headers: { Authorization: authHeader } });
      const base64 = Buffer.from(await resp.arrayBuffer()).toString('base64');
      screenshots.push({ mimeType: 'image/png', base64, source: 'attachment' }); // assume png for fetched
    }
  }
  return screenshots;
}

async function callGeminiMultimodal(systemText: string, userText: string, images: BugScreenshot[]) {
  const parts: any[] = [{ text: systemText + '\n\n' + userText }]; // text first...

  for (const img of images) {
    parts.push({ inlineData: { mimeType: img.mimeType, data: img.base64 } }); // ...then image bytes...
    parts.push({ text: `[Screenshot attached above — ${img.source} image]` }); // ...then a label so the model can tell them apart
  }

  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GOOGLE_API_KEY}`;
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    // temp 0.2 = near-deterministic steps; 8192 tokens = room for a full numbered test
    body: JSON.stringify({ contents: [{ parts }], generationConfig: { maxOutputTokens: 8192, temperature: 0.2 } }),
  });

  const data = await response.json();
  // Defensive dig: '' (not a throw) if blocked/no candidate — caller falls back on empty
  const answer = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
  return { answer, timeMs: Date.now(), model: 'gemini-2.0-flash' };
}

private async generateTestCase(bug: RawBug, input: AgentInput): Promise<GeneratedTestCase> {
  const intel = loadStoryIntelligence(bug);
  const systemPrompt = buildSystemPrompt(input.appUrl);
  const userPrompt = buildUserPrompt(bug, intel);

  let screenshots: BugScreenshot[] = [];
  if (input.includeScreenshots) screenshots = await extractScreenshots(bug); // --no-screenshots skips this

  // Guard 1: no API key -> skip Gemini entirely, use the rule-based skeleton
  let llmOutput = GOOGLE_API_KEY
    ? parseLLMJson<LLMTestCaseOutput>((await callGeminiMultimodal(systemPrompt, userPrompt, screenshots)).answer)
    : buildFallbackTestCase(bug, input.appUrl);

  if (!llmOutput) llmOutput = buildFallbackTestCase(bug, input.appUrl); // Guard 2: key present but parse failed

  const steps = (llmOutput.steps || []).map(s => ({ ...s })); // clone so renumbering doesn't mutate source

  // Invariant: step 1 is ALWAYS sign-in — insert + renumber if the model forgot
  if (steps.length === 0 || !steps[0].action.toLowerCase().includes('navigate')) {
    steps.unshift({
      stepNumber: 1,
      action: `Navigate to ${input.appUrl} and sign in with your organization's SSO credentials.`,
      expectedResult: 'The app home page loads with the main navigation visible.',
    });
    steps.forEach((s, idx) => { s.stepNumber = idx + 1; }); // keep numbering 1..N contiguous
  }

  return { bugId: bug.id, title: llmOutput.title, steps, qualityAssessment: llmOutput.qualityAssessment || 'poor' } as GeneratedTestCase;
}

private buildPersonSummary(testCases: GeneratedTestCase[]) {
  const map = new Map<string, { good: number; partial: number; poor: number }>();

  for (const tc of testCases) {
    const name = tc.reportedBy || 'Unknown'; // attribute unlabeled tickets somewhere
    if (!map.has(name)) map.set(name, { good: 0, partial: 0, poor: 0 });
    // qualityAssessment is 'good'|'partial'|'poor' — use it directly as the counter key
    map.get(name)![tc.qualityAssessment]++;
  }

  return Array.from(map.entries())
    .map(([name, counts]) => {
      const total = counts.good + counts.partial + counts.poor;
      // Score: good=100%, partial=50%, poor=0% — weighted average (partial = half a good)
      const score = total > 0 ? Math.round(((counts.good + counts.partial * 0.5) / total) * 100) : 0;
      return { name, total, ...counts, score };
    })
    // Rank by score desc; higher volume breaks ties so a track record beats a one-off
    .sort((a, b) => b.score - a.score || b.total - a.total);
}
